const query = $json.query ?? {};
const cuisines = ['german', 'italian', 'indian', 'japanese', 'gourmet', 'fusion'];
const rawId = typeof query.id === 'string' ? query.id.trim() : '';
const rawCuisine = typeof query.cuisine === 'string' ? query.cuisine.trim() : '';
const rawPage = typeof query.page === 'string' ? query.page.trim() : '1';
const page = Number(rawPage);
const errors = [];

if (rawId && (rawCuisine || rawPage !== '1')) errors.push('id darf nicht mit Filter/Pagination kombiniert werden.');
if (rawCuisine && !cuisines.includes(rawCuisine)) errors.push('Unbekannte Cuisine.');
if (!Number.isInteger(page) || page < 1) errors.push('page muss eine positive Ganzzahl sein.');
if (rawId && /[.#$\[\]\/]/.test(rawId)) errors.push('Ungültige Recipe-ID.');

return [{ json: { valid: errors.length === 0, id: rawId || null, cuisine: rawCuisine || null, page, errorMessage: errors.join(' ') } }];

const request = $('Normalize Library Request').item.json;
const raw = $json;
const records = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
const allowedCuisines = ['german', 'italian', 'indian', 'japanese', 'gourmet', 'fusion'];

function fail(message) { throw new Error(message); }
function validRecord(id, record) {
  if (!record || typeof record !== 'object' || Array.isArray(record)) fail('Ungültiger Firebase-Record.');
  if (record.schemaVersion !== 2 || typeof record.createdAt !== 'string' || Number.isNaN(Date.parse(record.createdAt))) fail('Ungültige Firebase-Metadaten.');
  const recipe = record.payload;
  if (!recipe || typeof recipe !== 'object' || Array.isArray(recipe) || recipe.id !== id) fail('Ungültiger Firebase-Recipe-Payload.');
  if (typeof recipe.title !== 'string' || !recipe.title.trim()) fail('Recipe-Titel fehlt.');
  if (!allowedCuisines.includes(recipe.cuisine)) fail('Recipe-Cuisine ist ungültig.');
  return { recipe, createdAt: record.createdAt };
}

if (request.id) {
  const record = records[request.id];
  if (!record) return [{ json: { recipe: null } }];
  return [{ json: { recipe: validRecord(request.id, record).recipe } }];
}

let items = Object.entries(records).map(([id, record]) => validRecord(id, record));
if (request.cuisine) items = items.filter((item) => item.recipe.cuisine === request.cuisine);
items.sort((a, b) => b.createdAt.localeCompare(a.createdAt) || String(a.recipe.id).localeCompare(String(b.recipe.id)));
const total = items.length;
const pageSize = 20;
const pages = Math.max(1, Math.ceil(total / pageSize));
const page = Math.min(request.page, pages);
const offset = (page - 1) * pageSize;
return [{ json: { items: items.slice(offset, offset + pageSize).map((item) => item.recipe), total, page, pages } }];
